import React from "react";
import CityData from "./cityData";

const RoutePlanner = ({ userData, onProceed }) => {
  const city = userData?.city;
  const places = CityData[city] || [];

  return (
    <div style={{ textAlign: "center", padding: "20px", background: "#fff8e7", minHeight: "100vh" }}>
      <h1>🌍 My Journey</h1>
      <h3>Welcome, {userData.name}! Here are some recommended places in {city}.</h3>

      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "20px", marginTop: "30px" }}>
        {places.length > 0 ? (
          places.map((place, index) => (
            <div
              key={index}
              style={{
                background: "white",
                borderRadius: "15px",
                boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
                padding: "15px",
                width: "300px",
                transition: "transform 0.3s",
              }}
              onMouseEnter={(e) => (e.currentTarget.style.transform = "scale(1.05)")}
              onMouseLeave={(e) => (e.currentTarget.style.transform = "scale(1)")}
            >
              <img
                src={place.img}
                alt={place.name}
                style={{ width: "100%", height: "180px", borderRadius: "10px", objectFit: "cover" }}
              />
              <h3>{place.name}</h3>
              <p>🕒 Best Time: {place.bestTime}</p>
              <p>⚠️ Crowd: {place.crowd}</p>
              <p>💡 Tip: {place.tip}</p>
            </div>
          ))
        ) : (
          <p>No curated places for this city yet. You can still proceed to plan your journey.</p>
        )}
      </div>

      <button
        onClick={onProceed}
        style={{
          marginTop: "40px",
          padding: "10px 25px",
          fontSize: "16px",
          background: "#ff914d",
          color: "white",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer",
        }}
      >
        🚶‍♂️ Start My Journey
      </button>
    </div>
  );
};

export default RoutePlanner;
